const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"快速進行唯讀檢查，確認印表機已就緒可開始列印。"}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"重新檢查"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"檢查中…"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"可開始列印"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"尚未就緒，無法列印"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"無法連線到印表機"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 已就緒"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper 尚未就緒（狀態："},{t:4,k:"state"},{t:3,v:"）"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"目前沒有列印進行中"}},fail:{t:0,b:{t:2,i:[{t:3,v:"已有列印正在執行（"},{t:4,k:"state"},{t:3,v:"）"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"所有軸都已歸位"}},fail:{t:0,b:{t:2,i:[{t:3,v:"軸尚未歸位（"},{t:4,k:"axes"},{t:3,v:"）；開始列印時通常會先歸位"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"指南"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"列印前檢查指南"}},close:{t:0,b:{t:2,i:[{t:3}],s:"關閉"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"什麼是列印前檢查？"}},body:{t:0,b:{t:2,i:[{t:3}],s:"以唯讀方式查看印表機是否已就緒可開始列印：它不會移動或變更任何東西，只會回報狀態。硬性阻擋項目會讓結論變紅；警告僅供參考，不會造成阻擋。"}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"它會檢查什麼"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 已就緒（未關機或進入錯誤）、目前沒有列印正在執行，以及各軸是否已歸位（僅供參考，因為開始列印時通常會先歸位）。"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"詞彙表"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 狀態"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 自身的狀態 - 'ready'（就緒）表示已連線且閒置；'shutdown'（關機）或 'error'（錯誤）表示在排除前無法列印。"}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"歸位"}},def:{t:0,b:{t:2,i:[{t:3}],s:"讓各軸移動到其限位開關，使印表機知道工具頭的位置。大多數列印開始程序都會自動歸位。"}}}}}}};export{t as default};
